<div class="row g-3"><div class="col-lg-4"><div class="km-card p-3"><h4>Nouvel utilisateur</h4><form method="post" action="<?=e(base_url('users'))?>"><?=csrf_field()?><label class="form-label">Nom complet</label><input class="form-control" name="full_name" required><label class="form-label mt-2">Nom utilisateur</label><input class="form-control" name="username" required><label class="form-label mt-2">E-mail</label><input class="form-control" name="email"><label class="form-label mt-2">Téléphone</label><input class="form-control" name="phone"><label class="form-label mt-2">Rôle</label><select class="form-select" name="role_id"><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=e($r['label'])?></option><?php endforeach;?></select><label class="form-label mt-2">Mot de passe initial</label><input class="form-control" type="password" name="password" minlength="8" required><button class="btn btn-km mt-3">Créer</button></form></div></div><div class="col-lg-8"><div class="km-card p-3"><h4>Utilisateurs</h4><table class="table"><thead><tr><th>Nom</th><th>Rôle</th><th>Identifiant</th><th>Statut</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['role_label'])?></td><td><?=e($u['username'])?></td><td><?=e($u['status'])?></td><td><form method="post" action="<?=e(base_url('users/'.$u['id'].'/status'))?>" class="d-flex gap-1"><?=csrf_field()?><select class="form-select form-select-sm" name="status"><option <?=selected($u['status'],'ACTIVE')?>>ACTIVE</option><option <?=selected($u['status'],'INACTIVE')?>>INACTIVE</option><option <?=selected($u['status'],'LOCKED')?>>LOCKED</option></select><button class="btn btn-sm btn-outline-dark">OK</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div>